import React, { useState } from 'react';
import { createStore2Return } from '../../services/stockService';

const ReturnOperations = () => {
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);
    const [success, setSuccess] = useState(false);

    const [returnForm, setReturnForm] = useState({
        productCode: '',
        category: '',
        productName: '',
        size: '',
        color: '',
        quantity: 0,
        unitPrice: 0,
        totalPrice: 0,
        returnReason: ''
    });

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            setLoading(true);
            setError(null);
            setSuccess(false);

            const response = await createStore2Return(returnForm);
            if (response.success) {
                setSuccess(true);
                setReturnForm({
                    productCode: '',
                    category: '',
                    productName: '',
                    size: '',
                    color: '',
                    quantity: 0,
                    unitPrice: 0,
                    totalPrice: 0,
                    returnReason: ''
                });
            } else {
                setError(response.message);
            }
        } catch (err) {
            setError('İade işlemi sırasında bir hata oluştu');
        } finally {
            setLoading(false);
        }
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setReturnForm(prev => {
            const newForm = { ...prev, [name]: value };
            if (name === 'quantity' || name === 'unitPrice') {
                newForm.totalPrice = newForm.quantity * newForm.unitPrice;
            }
            return newForm;
        });
    };

    if (loading) {
        return (
            <div className="flex justify-center items-center h-screen">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500"></div>
            </div>
        );
    }

    return (
        <div className="p-6">
            <h1 className="text-3xl font-bold mb-8">Store 2 - İade İşlemleri</h1>

            <div className="bg-white rounded-lg shadow-md p-6">
                <h2 className="text-xl font-bold mb-4">Yeni İade Oluştur</h2>
                
                {error && (
                    <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded mb-4">
                        {error}
                    </div>
                )}

                {success && (
                    <div className="bg-green-100 border border-green-400 text-green-700 px-4 py-3 rounded mb-4">
                        İade işlemi başarıyla oluşturuldu
                    </div>
                )}

                <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <input
                        type="text"
                        name="productCode"
                        placeholder="Ürün Kodu"
                        className="border p-2 rounded"
                        value={returnForm.productCode}
                        onChange={handleInputChange}
                        required
                    />
                    <input
                        type="text"
                        name="category"
                        placeholder="Kategori"
                        className="border p-2 rounded"
                        value={returnForm.category}
                        onChange={handleInputChange}
                        required
                    />
                    <input
                        type="text"
                        name="productName"
                        placeholder="Ürün Adı"
                        className="border p-2 rounded"
                        value={returnForm.productName}
                        onChange={handleInputChange}
                        required
                    />
                    <input
                        type="text"
                        name="size"
                        placeholder="Beden"
                        className="border p-2 rounded"
                        value={returnForm.size}
                        onChange={handleInputChange}
                        required
                    />
                    <input
                        type="text"
                        name="color"
                        placeholder="Renk"
                        className="border p-2 rounded"
                        value={returnForm.color}
                        onChange={handleInputChange}
                        required
                    />
                    <input
                        type="number"
                        name="quantity"
                        placeholder="Miktar"
                        className="border p-2 rounded"
                        value={returnForm.quantity}
                        onChange={handleInputChange}
                        required
                        min="1"
                    />
                    <input
                        type="number"
                        name="unitPrice"
                        placeholder="Birim Fiyat"
                        className="border p-2 rounded"
                        value={returnForm.unitPrice}
                        onChange={handleInputChange}
                        required
                        min="0"
                    />
                    <div className="border p-2 rounded bg-gray-50">
                        Toplam Tutar: {new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY' })
                            .format(returnForm.totalPrice)}
                    </div>
                    <div className="md:col-span-2">
                        <textarea
                            name="returnReason"
                            placeholder="İade Nedeni"
                            className="w-full border p-2 rounded"
                            value={returnForm.returnReason}
                            onChange={handleInputChange}
                            required
                            rows="3"
                        />
                    </div>
                    <div className="md:col-span-2">
                        <button 
                            type="submit" 
                            className="w-full bg-blue-500 text-white p-2 rounded hover:bg-blue-600"
                            disabled={loading}
                        >
                            {loading ? 'İşleniyor...' : 'İade Oluştur'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
};

export default ReturnOperations;
